@given("an order has been placed and is pending fulfillment")
def order_placed_pending_fulfillment_step(world: World) -> None:
    assert world.state.order_id, "the @needsOrder hook did not create an order"
    order = _order(world)
    assert order.get("status") == "ORDER_STATUS_PENDING", f"unexpected order status: {order}"
    assert order.get("buyerId") == _buyer(world).user_id, f"order is not the buyer's: {order}"
    assert order.get("sellerId") == _seller(world).user_id, f"order is not the seller's: {order}"

# c1_steps.py::other_seller_ships
@when("another seller tries to create a shipment for the order")
def other_seller_ships(world: World) -> None:
    password = world.settings.seed_password
    token = world.service_factory.auth.register(fake.unique_username("seller"), password, "seller")
    world.service_factory.set_token(token)
    code = f"SPX-NOPE-{uuid.uuid4().hex[:8].upper()}"
    status = None
    try:
        world.service_factory.order.create_shipment(
            order_id=world.state.order_id, carrier="SPX Express", tracking_code=code
        )
    except GatewayError as exc:
        status = exc.status
    _x(world)["rejected_tracking"] = code
    _x(world)["rejected_status"] = status

